export const MONUMENTS = JSON.parse("[{\"id\":\"n7804519467\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. В. Струве\",\"x\":-1711.7,\"z\":-1116.5,\"subject\":\"Q647712\",\"inscription\":\"Здесь с 1948 по 1965 год жил выдающийся историк и востоковед, академик Василий Васильевич Струве\"},{\"id\":\"n5553493449\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Dioscorides\",\"x\":-1842.3,\"z\":-1012.2},{\"id\":\"n5553493450\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Pheidon\",\"x\":-1853.6,\"z\":-1027},{\"id\":\"n5553493451\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Pichler\",\"x\":-1842.9,\"z\":-1007},{\"id\":\"n5661727654\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Б. Б. Пиотровскому\",\"x\":-1695.8,\"z\":-1032,\"subject\":\"Q481605\",\"inscription\":\"В этом доме жил директор Эрмитажа, академик Борис Борисович Пиотровский (1908–1990)\"},{\"id\":\"n8901819748\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Л. Н. Рахманову\",\"x\":-1195.8,\"z\":-1078.3,\"subject\":\"Q4391162\",\"inscription\":\"В этом доме с 1950 по 1988 год жил писатель Леонид Николаевич Рахманов\"},{\"id\":\"n8901825369\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Ю. П. Герману\",\"x\":-1210,\"z\":-1114.9,\"subject\":\"Q4137236\",\"inscription\":\"В этом доме с 1948 по 1967 год жил выдающийся советский писатель Юрий Павлович Герман\"},{\"id\":\"n8901831107\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"П. Л. Шиллингу фон Канштадту\",\"x\":-1198.6,\"z\":-1090.1,\"subject\":\"Q717731\",\"inscription\":\"Здесь жил и умер русский изобретатель электро-магнитного телеграфа барон Павел Львович Шиллинг фон Канштадт, родился 5 апреля 1786 г., умер 25 июля 1837 г.\"},{\"id\":\"n8901831538\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. В. Баранову\",\"x\":-1204.1,\"z\":-1104.3,\"subject\":\"Q4077759\",\"inscription\":\"Здесь жил и работал Народный архитектор СССР, академик архитектуры, главный архитектор Ленинграда с 1938 по 1950 год Николай Варфоломеевич Баранов\"},{\"id\":\"n9023403705\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"К. Л. Хетагурову\",\"x\":-1571.9,\"z\":-1099.6,\"subject\":\"Q368956\",\"inscription\":\"В этом доме жил основоположник осетинского литературного языка, выдающийся поэт и художник, революционный демократ Коста Леванович Хетагуров\"},{\"id\":\"n9749742039\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"П. В. Самойлову\",\"x\":-1286.7,\"z\":-1106.6,\"subject\":\"Q4406715\",\"inscription\":\"В этом доме с 1898 года жил и в 1931 году умер заслуженный артист РСФСР Павел Васильевич Самойлов\"},{\"id\":\"n1948007159\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Порфировая ваза\",\"x\":-814,\"z\":-1057.1,\"startDate\":\"1839\",\"wikidata\":\"Q4373478\",\"wikipedia\":\"ru:Порфировая ваза\"},{\"id\":\"n2513007719\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Чижик-Пыжик\",\"x\":-741.5,\"z\":-1033.8,\"h\":0.11,\"material\":\"bronze\",\"startDate\":\"1994-11-19\",\"wikidata\":\"Q16270744\",\"wikipedia\":\"ru:Памятник Чижику-Пыжику\"},{\"id\":\"n5736313317\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Героической обороне полуострова Ханко\",\"x\":-513.3,\"z\":-1114.6,\"subject\":\"Q384680\",\"inscription\":\"Слава великому советскому народу! Доска воздвигнута в честь героической обороны полуострова Ханко (22 июня — 2 декабря 1941 г.) в Великой Отечественной войне 1941—1945 гг. Слава мужественным защитникам полуострова Ханко!\"},{\"id\":\"n5736313318\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. А. Лягину\",\"x\":-569.3,\"z\":-1096.1,\"subject\":\"Q4272485\",\"inscription\":\"В этом доме с 1934 по 1939 годы жил Герой Советского Союза чекист-разведчик Виктор Александрович Лягин, руководитель подпольного центра в городе Николаеве в годы Великой Отечественной войны\"},{\"id\":\"n5736313320\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Ли Бом Джину\",\"x\":-592.5,\"z\":-1092.7,\"inscription\":\"Здесь жил и работал с 1901 по 1905 год первый постоянный чрезвычайный и полномочный посланник Кореи в Российской империи принц Ли Бом Джин\"},{\"id\":\"n8777372349\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"П. А. Столыпину\",\"x\":-632.1,\"z\":-1001.1,\"subject\":\"Q138487\",\"inscription\":\"Председатель совета министров, министр внутренних дел Российской Империи Петр Аркадьевич Столыпин работал в этом здании в 1906-1911 годах\"},{\"id\":\"n8960771420\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Центральному бюро петербургских профрабсоюзов\",\"x\":-661.9,\"z\":-1107.1,\"inscription\":\"Здесь в 1905 г. помещалось первое Центральное бюро петербургских профессиональных рабочих союзов, заложившее в своей работе основание Ленинградскому совету профсоюзов\"},{\"id\":\"n8960784054\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Первому съезду русских деятелей профессионального и технического образования\",\"x\":-623.8,\"z\":-1112.5,\"inscription\":\"В этом доме с 26 декабря 1889 г. по 6 января 1890 г. проходил I-ый съезд русских деятелей профессионального и технического образования\"},{\"id\":\"n8960784248\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-568.8,\"z\":-1116.7,\"material\":\"marble\",\"inscription\":\"Сей храм воздвигнут в царствование императора Петра Великого в 1721 году в благодарение Богу за дарованные нам морские победы над шведами в день Святого Великомученика Пантелеймона 27 июля при Гангуте в 1714 году и при Гренгамне в 1720 году.\"},{\"id\":\"n14135508014\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-559.2,\"z\":-1117.1,\"material\":\"marble\"},{\"id\":\"n14135508015\",\"kind\":\"artwork\",\"sub\":\"relief\",\"x\":-577.8,\"z\":-1115.1},{\"id\":\"n7743145488\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Профессор Преображенский и Шарик\",\"x\":-360.1,\"z\":-1026.9},{\"id\":\"n11100845322\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. Н. Коковцову\",\"x\":-347.7,\"z\":-1031.4,\"subject\":\"Q438448\",\"inscription\":\"В этом доме с 1914 по 1918 год жил председатель Совета министров, министр финансов Российской империи граф Владимир Николаевич Коковцов\"},{\"id\":\"n5546742983\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. А. Орбели\",\"x\":-1875.3,\"z\":-1157.8,\"subject\":\"Q1382698\",\"inscription\":\"В этом доме с 1948 по 1961 год жил выдающийся советский востоковед академик Иосиф Абгарович Орбели\"},{\"id\":\"n5900730042\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Д. Кваренги\",\"x\":-1890.6,\"z\":-1146.9,\"subject\":\"Q128623\",\"inscription\":\"В этом доме жил архитектор Джакомо Кваренги с 1809 по 1817 год.\"},{\"id\":\"n5546742951\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Paracius\",\"x\":-1996.2,\"z\":-1038.3,\"subject\":\"Q552759\"},{\"id\":\"n5546742952\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Apelles\",\"x\":-1992.6,\"z\":-1033.6,\"subject\":\"Q216822\"},{\"id\":\"n5546742953\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Zeyxis\",\"x\":-1989.1,\"z\":-1029,\"subject\":\"Q197044\"},{\"id\":\"n5546742954\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Timanoa\",\"x\":-1985.6,\"z\":-1024.3,\"subject\":\"Q6146976\"},{\"id\":\"n5546742955\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Polygnotos\",\"x\":-1982.1,\"z\":-1019.7,\"subject\":\"Q182855\"},{\"id\":\"n5553493445\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Raphael\",\"x\":-1976.3,\"z\":-1008.9,\"subject\":\"Q5597\"},{\"id\":\"n5570352159\",\"kind\":\"artwork\",\"sub\":\"statue\",\"name\":\"Rembrant\",\"x\":-1975.9,\"z\":-1009.2,\"subject\":\"Q5598\"},{\"id\":\"n5736313315\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"М. П. Мусоргскому, Н. А. Римскому-Корсакову, П. И. Чайковскому\",\"x\":-486.8,\"z\":-1125.1,\"inscription\":\"В этом доме во 2-й половине XIX века жили и работали великие русские композиторы М. П. Мусоргский, Н. А. Римский-Корсаков, П. И. Чайковский\"},{\"id\":\"n8960783943\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. А. Гаврилину\",\"x\":-303.6,\"z\":-1158.7,\"subject\":\"Q429147\",\"inscription\":\"В этом доме с 1980 по 1995 год жил и работал композитор Валерий Александрович Гаврилин\"},{\"id\":\"n14135508016\",\"kind\":\"artwork\",\"sub\":\"relief\",\"x\":-554.8,\"z\":-1120.2},{\"id\":\"n12100701246\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Ленину\",\"x\":499.3,\"z\":-1023.7},{\"id\":\"n10862756260\",\"kind\":\"artwork\",\"sub\":\"graffiti\",\"name\":\"С добрым утром, солнышко!\",\"x\":-256.6,\"z\":-1111.3},{\"id\":\"n5738911343\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"К. Ф. Рылееву\",\"x\":-34.7,\"z\":-1122.9,\"subject\":\"Кондратий Фёдорович Рылеев\",\"inscription\":\"Рылеев Кондратий Федорович, 1795—1826, поэт-декабрист, один из руководителей Северного общества декабристов, активный участник восстания на Сенатской площади в Петербурге 14 (26) декабря 1825 года...\"},{\"id\":\"n9951473955\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"Говоров Леонид Александрович\",\"x\":332.6,\"z\":-1048},{\"id\":\"n10283929794\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. А. Бродскому\",\"x\":-137.9,\"z\":-1135.4,\"subject\":\"Q862\",\"inscription\":\"В этом доме с 1955 по 1972 год жил поэт Иосиф Александрович Бродский\"},{\"id\":\"n8901836694\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. Ф. Пановой\",\"x\":-1212.1,\"z\":-1120.1,\"subject\":\"Q262850\",\"inscription\":\"Здесь с 1948 года по 1970 год жила и работала писательница Вера Федоровна Панова\"},{\"id\":\"n5825840043\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Е. Н. Павловскому\",\"x\":-2536.2,\"z\":-1134.9,\"subject\":\"Q1046549\",\"inscription\":\"Здесь с 1924 г. по 1965 г. работал выдающийся зоолог, Герой Социалистического Труда, академик Евгений Никанорович Павловский\"},{\"id\":\"n12469385514\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"Бэру К.М.\",\"x\":-2543.3,\"z\":-1141.9},{\"id\":\"n12469385515\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Памяти сотрудников Зоологического института\",\"x\":-2548,\"z\":-1144.6}]");
